#![no_std]

//! C-ABI entry points into `sha3` 0.12.0, seven per hasher type, generated by `entry_points!`.
//! `Sha3/Spec/Program.lean` specifies each call. Slices come as tables: `input[i]` holds the
//! address of slice `i` and `input_lens[i]` its length, for `i < num_inputs`. `split` counts the
//! slices before the reset and may exceed `num_inputs`. Each two-output form makes exactly one
//! reset, at the split, and writes one digest before it and one after it.

use sha3::digest::{Digest, FixedOutput, FixedOutputReset, Output, Reset, Update};

/// The `num_inputs` slices whose addresses are at `input` and whose lengths are at `input_lens`.
unsafe fn inputs<'a>(
    input: *const *const u8,
    num_inputs: usize,
    input_lens: *const usize,
) -> impl Iterator<Item = &'a [u8]> {
    let pointers = unsafe { core::slice::from_raw_parts(input, num_inputs) };
    let lengths = unsafe { core::slice::from_raw_parts(input_lens, num_inputs) };
    pointers
        .iter()
        .zip(lengths)
        .map(|(&pointer, &length)| unsafe { core::slice::from_raw_parts(pointer, length) })
}

/// The traits every hasher type implements, and the conversion of an output array.
trait Hasher<const N: usize>: Digest + Default + Update + FixedOutputReset {
    fn output(out: &mut [u8; N]) -> &mut Output<Self>;
}

impl<H, const N: usize> Hasher<N> for H
where
    H: Digest + Default + Update + FixedOutputReset,
    for<'a> &'a mut Output<H>: From<&'a mut [u8; N]>,
{
    fn output(out: &mut [u8; N]) -> &mut Output<Self> {
        out.into()
    }
}

#[inline(always)]
unsafe fn digest<H: Hasher<N>, const N: usize>(data: *const u8, len: usize, out: *mut [u8; N]) {
    let data = unsafe { core::slice::from_raw_parts(data, len) };
    let digest = <H as Digest>::digest(data);
    unsafe { &mut *out }.copy_from_slice(&digest);
}

#[inline(always)]
unsafe fn digest_slices<H: Hasher<N>, const N: usize>(
    input: *const *const u8,
    num_inputs: usize,
    input_lens: *const usize,
    out: *mut [u8; N],
) {
    let mut hasher = <H as Digest>::new();
    for slice in unsafe { inputs(input, num_inputs, input_lens) } {
        Digest::update(&mut hasher, slice);
    }
    let digest = Digest::finalize(hasher);
    unsafe { &mut *out }.copy_from_slice(&digest);
}

#[inline(always)]
unsafe fn reset<H: Hasher<N>, const N: usize>(
    input: *const *const u8,
    num_inputs: usize,
    input_lens: *const usize,
    out: *mut [u8; N],
    split: usize,
) {
    let mut hasher = H::default();
    let mut slices = unsafe { inputs(input, num_inputs, input_lens) };
    for slice in slices.by_ref().take(split) {
        Update::update(&mut hasher, slice);
    }
    Reset::reset(&mut hasher);
    for slice in slices {
        Update::update(&mut hasher, slice);
    }
    FixedOutput::finalize_into(hasher, H::output(unsafe { &mut *out }));
}

/// The two-output forms: a new hasher absorbs the first `split` slices; one reset method writes
/// their digest to `first` and resets the hasher; the hasher absorbs the remaining slices; and a
/// plain finalize writes their digest to `second`.
#[inline(always)]
unsafe fn fixed_finalize_into_reset<H: Hasher<N>, const N: usize>(
    input: *const *const u8,
    num_inputs: usize,
    input_lens: *const usize,
    first: *mut [u8; N],
    split: usize,
    second: *mut [u8; N],
) {
    let mut hasher = H::default();
    let mut slices = unsafe { inputs(input, num_inputs, input_lens) };
    for slice in slices.by_ref().take(split) {
        Update::update(&mut hasher, slice);
    }
    FixedOutputReset::finalize_into_reset(&mut hasher, H::output(unsafe { &mut *first }));
    for slice in slices {
        Update::update(&mut hasher, slice);
    }
    FixedOutput::finalize_into(hasher, H::output(unsafe { &mut *second }));
}

#[inline(always)]
unsafe fn finalize_fixed_reset<H: Hasher<N>, const N: usize>(
    input: *const *const u8,
    num_inputs: usize,
    input_lens: *const usize,
    first: *mut [u8; N],
    split: usize,
    second: *mut [u8; N],
) {
    let mut hasher = H::default();
    let mut slices = unsafe { inputs(input, num_inputs, input_lens) };
    for slice in slices.by_ref().take(split) {
        Update::update(&mut hasher, slice);
    }
    let digest = FixedOutputReset::finalize_fixed_reset(&mut hasher);
    unsafe { &mut *first }.copy_from_slice(&digest);
    for slice in slices {
        Update::update(&mut hasher, slice);
    }
    FixedOutput::finalize_into(hasher, H::output(unsafe { &mut *second }));
}

#[inline(always)]
unsafe fn digest_finalize_into_reset<H: Hasher<N>, const N: usize>(
    input: *const *const u8,
    num_inputs: usize,
    input_lens: *const usize,
    first: *mut [u8; N],
    split: usize,
    second: *mut [u8; N],
) {
    let mut hasher = <H as Digest>::new();
    let mut slices = unsafe { inputs(input, num_inputs, input_lens) };
    for slice in slices.by_ref().take(split) {
        Digest::update(&mut hasher, slice);
    }
    Digest::finalize_into_reset(&mut hasher, H::output(unsafe { &mut *first }));
    for slice in slices {
        Digest::update(&mut hasher, slice);
    }
    Digest::finalize_into(hasher, H::output(unsafe { &mut *second }));
}

#[inline(always)]
unsafe fn digest_finalize_reset<H: Hasher<N>, const N: usize>(
    input: *const *const u8,
    num_inputs: usize,
    input_lens: *const usize,
    first: *mut [u8; N],
    split: usize,
    second: *mut [u8; N],
) {
    let mut hasher = <H as Digest>::new();
    let mut slices = unsafe { inputs(input, num_inputs, input_lens) };
    for slice in slices.by_ref().take(split) {
        Digest::update(&mut hasher, slice);
    }
    let digest = Digest::finalize_reset(&mut hasher);
    unsafe { &mut *first }.copy_from_slice(&digest);
    for slice in slices {
        Digest::update(&mut hasher, slice);
    }
    Digest::finalize_into(hasher, H::output(unsafe { &mut *second }));
}

/// Exports one two-output entry point, `$name`, calling `$form`.
macro_rules! two_output_entry_point {
    ($hasher:ty, $n:literal, $name:ident, $form:ident) => {
        #[unsafe(no_mangle)]
        pub unsafe extern "C" fn $name(
            input: *const *const u8,
            num_inputs: usize,
            input_lens: *const usize,
            first: *mut [u8; $n],
            split: usize,
            second: *mut [u8; $n],
        ) {
            unsafe { $form::<$hasher, $n>(input, num_inputs, input_lens, first, split, second) }
        }
    };
}

/// Exports the seven entry points of one hasher type, named `<prefix>_<form>`.
macro_rules! entry_points {
    ($hasher:ty, $n:literal, $digest:ident, $digest_slices:ident, $reset:ident,
     $fixed_finalize_into_reset:ident, $finalize_fixed_reset:ident,
     $digest_finalize_into_reset:ident, $digest_finalize_reset:ident $(,)?) => {
        #[unsafe(no_mangle)]
        pub unsafe extern "C" fn $digest(data: *const u8, len: usize, out: *mut [u8; $n]) {
            unsafe { digest::<$hasher, $n>(data, len, out) }
        }

        #[unsafe(no_mangle)]
        pub unsafe extern "C" fn $digest_slices(
            input: *const *const u8,
            num_inputs: usize,
            input_lens: *const usize,
            out: *mut [u8; $n],
        ) {
            unsafe { digest_slices::<$hasher, $n>(input, num_inputs, input_lens, out) }
        }

        #[unsafe(no_mangle)]
        pub unsafe extern "C" fn $reset(
            input: *const *const u8,
            num_inputs: usize,
            input_lens: *const usize,
            out: *mut [u8; $n],
            split: usize,
        ) {
            unsafe { reset::<$hasher, $n>(input, num_inputs, input_lens, out, split) }
        }

        two_output_entry_point!(
            $hasher, $n, $fixed_finalize_into_reset, fixed_finalize_into_reset
        );
        two_output_entry_point!(
            $hasher, $n, $finalize_fixed_reset, finalize_fixed_reset
        );
        two_output_entry_point!(
            $hasher, $n, $digest_finalize_into_reset, digest_finalize_into_reset
        );
        two_output_entry_point!(
            $hasher, $n, $digest_finalize_reset, digest_finalize_reset
        );
    };
}

